    /**
     * Method to retrieve the Lot via LotFetchOneSummary
     * @param 	summary LotFetchOneSummary 
     * @return 	LotFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public Lot getLot( LotFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "LotFetchOneSummary arg cannot be null" );
    	
    	Lot entity = null;
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	validator.validate( summary );    
        	
        	// --------------------------------------
        	// use queryGateway to send request to Find a Lot
        	// --------------------------------------
        	CompletableFuture<Lot> futureEntity = queryGateway.query(new FindLotQuery( new LoadLotFilter( summary.getLotId() ) ), ResponseTypes.instanceOf(Lot.class));
        	
        	entity = futureEntity.get();
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate Lot with id " + summary.getLotId();
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


